function doubleEvens(numbers) {
  // Filter keeps only even numbers, then doubles them
  return numbers.filter(n => n % 2 === 0).map(n => n * 2);
}

// Result for [1, 2, 3, 4]
console.log(doubleEvens([1, 2, 3, 4])); 
// Output: [2, 4, 6, 8]

console.log("probe", JSON.stringify(doubleEvens([1, 2, 3, 4])), JSON.stringify(doubleEvens([-2, 3, 6])));

function doubleEvens(numbers) {
  return numbers
    .filter(n => n % 2 === 0)
    .map(n => n * 2);
}

console.log(doubleEvens([1, 2, 3, 4])); // [4, 8]

console.log("probe", JSON.stringify(doubleEvens([1, 2, 3, 4])), JSON.stringify(doubleEvens([-2, 3, 6])));

/**
 * Reverses a string.
 * 
 * @param {string} str - The string to reverse.
 * @returns {string} The reversed string.
 */
function reverseString(str) {
  return str.split('').reverse().join('');
}

// Example usage
console.log(reverseString("stressed")); 
// Output: "edresst"

console.log("probe", JSON.stringify(reverseString("stressed")));

